import{_ as t,o as d,c as o,al as a}from"./chunks/framework.CAAkqCQG.js";const y=JSON.parse('{"title":"Types","description":"Reference for the data types shared by every part of lognal, including LogEntry, LogPart, ValueNode, LogLevel, TextStyle and StyleToken.","frontmatter":{"order":6,"description":"Reference for the data types shared by every part of lognal, including LogEntry, LogPart, ValueNode, LogLevel, TextStyle and StyleToken.","head":[["link",{"rel":"canonical","href":"https://lognal.cdget.com/reference/types"}],["link",{"rel":"alternate","hreflang":"en","href":"https://lognal.cdget.com/reference/types"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://lognal.cdget.com/ko/reference/types"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://lognal.cdget.com/reference/types"}],["meta",{"property":"og:title","content":"Types | lognal"}],["meta",{"property":"og:description","content":"Reference for the data types shared by every part of lognal, including LogEntry, LogPart, ValueNode, LogLevel, TextStyle and StyleToken."}],["meta",{"property":"og:url","content":"https://lognal.cdget.com/reference/types"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Types | lognal"}],["meta",{"name":"twitter:description","content":"Reference for the data types shared by every part of lognal, including LogEntry, LogPart, ValueNode, LogLevel, TextStyle and StyleToken."}]]},"headers":[],"relativePath":"reference/types.md","filePath":"en/reference/types.md","lastUpdated":1789272545000}'),r={name:"reference/types.md"};function s(i,e,c,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h1><p>Everything in this page is plain data. An entry and its values hold no reference to the objects that were logged, so they can be passed through <code>postMessage</code> or saved as JSON.</p><h2 id="loglevel" tabindex="-1">LogLevel <a class="header-anchor" href="#loglevel" aria-label="Permalink to &quot;LogLevel&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LogLevel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;debug&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;log&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;info&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;warn&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The severity of an entry. <code>LOG_LEVELS</code> is a read-only array of every level, ordered from least to most severe.</p><h2 id="logkind" tabindex="-1">LogKind <a class="header-anchor" href="#logkind" aria-label="Permalink to &quot;LogKind&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LogKind</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;message&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;input&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;output&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;group&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;system&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>What an entry represents. The viewer marks each kind differently.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Entry</th></tr></thead><tbody><tr><td><code>&#39;message&#39;</code></td><td>A regular log message.</td></tr><tr><td><code>&#39;input&#39;</code></td><td>A command the user typed into the input line.</td></tr><tr><td><code>&#39;output&#39;</code></td><td>The reply to a command.</td></tr><tr><td><code>&#39;group&#39;</code></td><td>The header of a group started with <code>console.group</code>.</td></tr><tr><td><code>&#39;system&#39;</code></td><td>A notice from the viewer itself, such as <code>Console was cleared</code>.</td></tr></tbody></table><h2 id="logentry" tabindex="-1">LogEntry <a class="header-anchor" href="#logentry" aria-label="Permalink to &quot;LogEntry&quot;">​</a></h2><p>An entry held by a store.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>number</code></td><td>A number that identifies the entry in its store. Read-only.</td></tr><tr><td><code>time</code></td><td><code>number</code></td><td>When the entry was added, in epoch milliseconds. Read-only.</td></tr><tr><td><code>level</code></td><td><code>LogLevel</code></td><td>The severity. Read-only.</td></tr><tr><td><code>kind</code></td><td><code>LogKind</code></td><td>What the entry represents. Read-only.</td></tr><tr><td><code>parts</code></td><td><code>readonly LogPart[]</code></td><td>The content, displayed one part after another. Read-only.</td></tr><tr><td><code>groups</code></td><td><code>readonly number[]</code></td><td>The ids of the open groups the entry belongs to, outermost first. Read-only.</td></tr><tr><td><code>collapsed</code></td><td><code>boolean</code></td><td>For a group header, whether its members are hidden.</td></tr><tr><td><code>repeat</code></td><td><code>number</code></td><td>How many identical consecutive messages the entry stands for.</td></tr><tr><td><code>version</code></td><td><code>number</code></td><td>Increases whenever <code>collapsed</code> or <code>repeat</code> changes, so cached layouts can be refreshed.</td></tr></tbody></table><h2 id="logentryinit" tabindex="-1">LogEntryInit <a class="header-anchor" href="#logentryinit" aria-label="Permalink to &quot;LogEntryInit&quot;">​</a></h2><p>The fields you provide to <code>store.append</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>parts</code></td><td><code>LogPart[]</code></td><td>Required</td><td>The content of the entry.</td></tr><tr><td><code>level</code></td><td><code>LogLevel</code></td><td><code>&#39;log&#39;</code></td><td>The severity.</td></tr><tr><td><code>kind</code></td><td><code>LogKind</code></td><td><code>&#39;message&#39;</code></td><td>What the entry represents.</td></tr><tr><td><code>time</code></td><td><code>number</code></td><td>The time it is added</td><td>Epoch milliseconds.</td></tr><tr><td><code>groups</code></td><td><code>readonly number[]</code></td><td><code>[]</code></td><td>Ids of the open groups this entry belongs to, outermost first.</td></tr><tr><td><code>collapsed</code></td><td><code>boolean</code></td><td><code>false</code></td><td>For a group header, whether the group starts collapsed.</td></tr></tbody></table><h2 id="logpart" tabindex="-1">LogPart <a class="header-anchor" href="#logpart" aria-label="Permalink to &quot;LogPart&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LogPart</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TextPart</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ValuePart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="textpart" tabindex="-1">TextPart <a class="header-anchor" href="#textpart" aria-label="Permalink to &quot;TextPart&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>&#39;text&#39;</code></td><td>Marks a text part.</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>The text. It can contain line breaks.</td></tr><tr><td><code>token</code></td><td><code>StyleToken</code></td><td>A semantic color, optional.</td></tr><tr><td><code>style</code></td><td><code>TextStyle</code></td><td>Explicit styling, optional.</td></tr><tr><td><code>wrap</code></td><td><code>boolean</code></td><td><code>false</code> keeps every line of the part on one row, for text such as a table. Optional; parts wrap by default.</td></tr></tbody></table><h3 id="valuepart" tabindex="-1">ValuePart <a class="header-anchor" href="#valuepart" aria-label="Permalink to &quot;ValuePart&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>&#39;value&#39;</code></td><td>Marks a value part.</td></tr><tr><td><code>value</code></td><td><code>ValueNode</code></td><td>A captured value, from <code>snapshotValue</code>.</td></tr></tbody></table><h2 id="styletoken" tabindex="-1">StyleToken <a class="header-anchor" href="#styletoken" aria-label="Permalink to &quot;StyleToken&quot;">​</a></h2><p><code>StyleToken</code> is one of these strings: <code>&#39;default&#39;</code>, <code>&#39;muted&#39;</code>, <code>&#39;string&#39;</code>, <code>&#39;number&#39;</code>, <code>&#39;boolean&#39;</code>, <code>&#39;null&#39;</code>, <code>&#39;key&#39;</code>, <code>&#39;symbol&#39;</code>, <code>&#39;function&#39;</code>, <code>&#39;regexp&#39;</code>, <code>&#39;date&#39;</code>, <code>&#39;tag&#39;</code>, <code>&#39;attribute&#39;</code>, <code>&#39;error&#39;</code>, <code>&#39;warn&#39;</code>, <code>&#39;info&#39;</code>, <code>&#39;accent&#39;</code>.</p><p>A semantic color that the renderer resolves from the theme. Every token except <code>default</code> has a <code>--lognal-token-*</code> property. <code>default</code> uses the color of the entry&#39;s level.</p><h2 id="textstyle" tabindex="-1">TextStyle <a class="header-anchor" href="#textstyle" aria-label="Permalink to &quot;TextStyle&quot;">​</a></h2><p>Explicit styling, from <code>%c</code> in a console message or from ANSI escape codes.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>color</code></td><td><code>TextColor</code></td><td>The text color.</td></tr><tr><td><code>background</code></td><td><code>TextColor</code></td><td>The background color.</td></tr><tr><td><code>bold</code></td><td><code>boolean</code></td><td>Bold text.</td></tr><tr><td><code>dim</code></td><td><code>boolean</code></td><td>Text at lower opacity.</td></tr><tr><td><code>italic</code></td><td><code>boolean</code></td><td>Italic text.</td></tr><tr><td><code>underline</code></td><td><code>boolean</code></td><td>Underlined text.</td></tr><tr><td><code>strikethrough</code></td><td><code>boolean</code></td><td>Struck-through text.</td></tr></tbody></table><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TextColor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>A number from 0 to 255 is an index into the ANSI palette, where 0 to 15 follow the theme. A string is a CSS color such as <code>#ff0000</code> or <code>rgb(255 0 0)</code>.</p><h2 id="valuenode" tabindex="-1">ValueNode <a class="header-anchor" href="#valuenode" aria-label="Permalink to &quot;ValueNode&quot;">​</a></h2><p>A snapshot of a value, taken when it was logged.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>ValueKind</code></td><td>The kind of value.</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td>The text of a leaf value: the string itself, a number as text, a function name, a date in ISO format, a regular expression literal, an error message, or an element&#39;s tag name.</td></tr><tr><td><code>className</code></td><td><code>string</code></td><td>The constructor name of an object, such as <code>Map</code> or <code>User</code>.</td></tr><tr><td><code>size</code></td><td><code>number</code></td><td>The length of an array or string, or the size of a map or set.</td></tr><tr><td><code>children</code></td><td><code>ValueEntry[]</code></td><td>The captured children of an object, array, map, set, error or element. <code>undefined</code> when the depth limit was reached.</td></tr><tr><td><code>omitted</code></td><td><code>number</code></td><td>How many children exist but were left out because of a limit.</td></tr><tr><td><code>truncated</code></td><td><code>number</code></td><td>How many characters were cut from a long string.</td></tr><tr><td><code>stack</code></td><td><code>string</code></td><td>The stack trace of an error, without its first line.</td></tr><tr><td><code>attributes</code></td><td><code>[string, string][]</code></td><td>The attributes of an element, as name and value pairs.</td></tr><tr><td><code>accessor</code></td><td><code>&#39;get&#39; | &#39;set&#39; | &#39;get-set&#39;</code></td><td>For an accessor property, which parts are defined.</td></tr></tbody></table><p>Every field except <code>kind</code> is optional.</p><h3 id="valuekind" tabindex="-1">ValueKind <a class="header-anchor" href="#valuekind" aria-label="Permalink to &quot;ValueKind&quot;">​</a></h3><p><code>ValueKind</code> is one of these strings: <code>&#39;undefined&#39;</code>, <code>&#39;null&#39;</code>, <code>&#39;boolean&#39;</code>, <code>&#39;number&#39;</code>, <code>&#39;bigint&#39;</code>, <code>&#39;string&#39;</code>, <code>&#39;symbol&#39;</code>, <code>&#39;function&#39;</code>, <code>&#39;class&#39;</code>, <code>&#39;date&#39;</code>, <code>&#39;regexp&#39;</code>, <code>&#39;error&#39;</code>, <code>&#39;array&#39;</code>, <code>&#39;object&#39;</code>, <code>&#39;map&#39;</code>, <code>&#39;set&#39;</code>, <code>&#39;weak&#39;</code>, <code>&#39;promise&#39;</code>, <code>&#39;element&#39;</code>, <code>&#39;text&#39;</code>, <code>&#39;circular&#39;</code>, <code>&#39;accessor&#39;</code>.</p><p>Typed arrays are <code>&#39;array&#39;</code> with their class name, <code>WeakMap</code>, <code>WeakSet</code> and <code>WeakRef</code> are <code>&#39;weak&#39;</code>, and DOM text nodes are <code>&#39;text&#39;</code>.</p><h3 id="valueentry" tabindex="-1">ValueEntry <a class="header-anchor" href="#valueentry" aria-label="Permalink to &quot;ValueEntry&quot;">​</a></h3><p>A child of a value: a property, an array item, a map entry or a child node.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>key</code></td><td><code>string</code></td><td>The property name or index. Absent for set items and child nodes.</td></tr><tr><td><code>keyKind</code></td><td><code>&#39;property&#39; | &#39;index&#39; | &#39;symbol&#39; | &#39;internal&#39;</code></td><td>How the key is displayed.</td></tr><tr><td><code>keyValue</code></td><td><code>ValueNode</code></td><td>The key of a map entry.</td></tr><tr><td><code>value</code></td><td><code>ValueNode</code></td><td>The child value.</td></tr></tbody></table>',39)])])}const g=t(r,[["render",s]]);export{y as __pageData,g as default};
